/**
 * The internal sink contract behind `ctx.host.files` — durable, file-shaped
 * state that must outlive the engine process.
 *
 * Deliberately **not a filesystem**: no file descriptors, no seeking, no
 * rename, no directories as first-class objects, and no POSIX errno contract
 * — a sink that is an HTTP API can implement all of it. The framework
 * **mints every key** from a stable, versioned scheme (see {@link fileKeys});
 * sinks see opaque strings and never learn which deployment or session a key
 * belongs to, which is what keeps one deployment's files unreachable from
 * another's.
 *
 * Internal for now: the authored plug-in surface (`agent/files.ts` with a
 * `defineFiles`, mirroring `defineStorage`) is deliberately deferred so this
 * ships as exactly the hosted connector plus the local default. When it
 * lands, {@link FileSink} is the contract authored sinks implement.
 *
 * Delivery semantics differ from {@link import("./storage.js").defineStorage}
 * on purpose. Storage is a fire-and-forget mirror of framework state, so a
 * throwing `put` is logged and dropped. Files are author data the next turn
 * may depend on, so {@link HostFilesApi} writes are **awaited and surface
 * their failure** — an author who writes evidence and then delegates has to
 * know the write did not land.
 */
import { AGENTSDK_STORAGE_KEY_ROOT, STORAGE_KEY_ROOT } from "./storage.js";
// ============================================================================
// Key scheme
// ============================================================================
/**
 * The framework-owned file key scheme, a stable versioned contract under
 * {@link STORAGE_KEY_ROOT}. Sinks may treat these as opaque, or route on
 * prefixes.
 *
 * | Key | Holds |
 * | --- | --- |
 * | `agentkit/v1/{agent}/files/deployment/{path}` | Deployment-scoped file, shared by every session and surviving redeploys |
 * | `agentkit/v1/{agent}/files/deployment/{partition}/{path}` | Deployment-scoped file under an author partition (a PR, a customer, a branch) |
 * | `agentkit/v1/{agent}/files/sessions/{sessionId}/{path}` | Session-scoped file |
 *
 * Scoping lives here, above the sink, so a sink cannot be handed a key for a
 * deployment or session other than its own.
 */
export const fileKeys = {
    deployment: (agent, path) => `${STORAGE_KEY_ROOT}/${agent}/files/deployment/${path}`,
    deploymentPartition: (agent, partition, path) => `${STORAGE_KEY_ROOT}/${agent}/files/deployment/${partition}/${path}`,
    session: (agent, sessionId, path) => `${STORAGE_KEY_ROOT}/${agent}/files/sessions/${sessionId}/${path}`,
    deploymentPrefix: (agent) => `${STORAGE_KEY_ROOT}/${agent}/files/deployment/`,
    sessionPrefix: (agent, sessionId) => `${STORAGE_KEY_ROOT}/${agent}/files/sessions/${sessionId}/`,
};
/**
 * Stable identifier for the signed-in user's file store.
 */
export const AGENT_SERVE_USER_STORE_FILES_SOURCE_ID = "user";
/** Store-root prefix for agent data in a user file store. */
export const AGENT_SERVE_USER_STORE_KEY_PREFIX = "agent-serve";
/**
 * Framework-owned keys for artifacts, skills, workspace seeds, memory, and
 * conversation checkpoints. They stay outside author `host.files` listings.
 */
function createAgentStoreKeys(root) {
    return {
        artifactRow: (agent, id) => `${root}/${agent}/artifacts/rows/${encodeURIComponent(id)}.json`,
        artifactRowPrefix: (agent) => `${root}/${agent}/artifacts/rows/`,
        artifactContent: (agent, id) => `${root}/${agent}/artifacts/content/${encodeURIComponent(id)}`,
        skillFile: (skillName, relPath, skillsPrefix = "skills/") => `${skillsPrefix}${skillName}/${relPath}`,
        skillsPrefix: () => "skills/",
        /** Personal-key cloud agents: namespaced so they cannot collide with the user's own `skills/`. */
        userSkillsPrefix: (agent) => `${AGENT_SERVE_USER_STORE_KEY_PREFIX}/${agent}/skills/`,
        workspaceFile: (relPath, workspacePrefix = "workspace/") => `${workspacePrefix}${relPath}`,
        workspacePrefix: () => "workspace/",
        /** Personal-key cloud agents: namespaced like {@link userSkillsPrefix}. */
        userWorkspacePrefix: (agent) => `${AGENT_SERVE_USER_STORE_KEY_PREFIX}/${agent}/workspace/`,
        sessionWorkspacePrefix: (sessionId) => `sessions/${sessionId}/workspace/`,
        /** Personal-key cloud agents: namespaced like {@link sessionWorkspacePrefix}. */
        userSessionWorkspacePrefix: (agent, sessionId) => `${AGENT_SERVE_USER_STORE_KEY_PREFIX}/${agent}/sessions/${sessionId}/workspace/`,
        memoryDir: (agent) => `${root}/${agent}/memory`,
        memoryJournal: (agent) => `${root}/${agent}/memory/journal.jsonl`,
        memoryJournalRotated: (agent, stamp) => `${root}/${agent}/memory/journal-${stamp}.jsonl`,
        // One conversation manifest plus the checkpoint blobs it references:
        // content-addressed packs (manifest v2) or one object per blob (v1).
        conversationManifest: (agent, sdkAgentId) => `${root}/${agent}/conversations/${encodeURIComponent(sdkAgentId)}/manifest.json`,
        conversationPack: (agent, sdkAgentId, packId) => `${root}/${agent}/conversations/${encodeURIComponent(sdkAgentId)}/packs/${encodeURIComponent(packId)}`,
        conversationBlob: (agent, sdkAgentId, blobId) => `${root}/${agent}/conversations/${encodeURIComponent(sdkAgentId)}/blobs/${encodeURIComponent(blobId)}`,
    };
}
export const agentStoreKeys = createAgentStoreKeys(STORAGE_KEY_ROOT);
export const agentSdkAgentStoreKeys = createAgentStoreKeys(AGENTSDK_STORAGE_KEY_ROOT);
/** Mounted path for deployment files when the host exposes one. */
export const DEPLOYMENT_STORE_MOUNT_PATH = "/cursor/stores/deployment";
/** Mounted path for user files when the host exposes one. */
export const USER_STORE_MOUNT_PATH = "/cursor/stores/user";
/** Errors raised by the file surface. Thrown by sinks and by the framework. */
export class FileConflictError extends Error {
    constructor(key, options) {
        super(`host.files write for "${key}" lost a race with another writer${options?.storedEtag === undefined ? "" : ` (stored version ${options.storedEtag})`}`);
        this.key = key;
        this.name = "FileConflictError";
        if (options?.cause !== undefined) {
            this.cause = options.cause;
        }
        if (options?.storedEtag !== undefined) {
            this.storedEtag = options.storedEtag;
        }
    }
}
/** A path the framework refuses to mint a key for. */
export class FilePathRejectedError extends Error {
    constructor(message) {
        super(message);
        this.name = "FilePathRejectedError";
    }
}
/** A session-scoped call with no session in scope. */
export class FileSessionRequiredError extends Error {
    constructor(message) {
        super(message);
        this.name = "FileSessionRequiredError";
    }
}
/** A value larger than the sink accepts. */
export class FileTooLargeError extends Error {
    constructor(key, size, maxBytes) {
        super(`host.files value for "${key}" is ${size} bytes, over the sink's ${maxBytes}-byte limit`);
        this.key = key;
        this.size = size;
        this.maxBytes = maxBytes;
        this.name = "FileTooLargeError";
    }
}
